package com.thralloverhead;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("thrallTimer")
public interface ThrallOverheadConfig extends Config
{
    @ConfigItem(
        keyName = "showTimer",
        name = "Show Thrall Timer",
        description = "Display the timer above summoned thralls"
    )
    default boolean showTimer()
    {
        return true;
    }

    @Range(min = 20, max = 100)
    @ConfigItem(
        keyName = "barWidth",
        name = "Bar Width",
        description = "Width of the thrall timer bar (20-100)"
    )
    default int barWidth()
    {
        return 40;
    }

    @Range(min = 2, max = 15)
    @ConfigItem(
        keyName = "barHeight",
        name = "Bar Height",
        description = "Height of the thrall timer bar (2-15)"
    )
    default int barHeight()
    {
        return 5;
    }

	@ConfigItem(
    keyName = "showBorder",
    name = "Show Border",
    description = "Display a border around the thrall timer bar"
	)
	default boolean showBorder()
	{
		return false;
	}

    @Range(min = 0, max = 100)
    @ConfigItem(
        keyName = "barOffset",
        name = "Bar Vertical Offset",
        description = "Adjust the vertical position of the timer (0-100)"
    )
    default int barOffset()
    {
        return 35;
    }

    @ConfigItem(
        keyName = "flashWarning",
        name = "Flash Warning",
        description = "Flash the background when a thrall is about to expire"
    )
    default boolean flashWarning()
    {
        return true;
    }

    @Range(min = 1, max = 30)
    @ConfigItem(
        keyName = "warningThreshold",
        name = "Warning Threshold",
        description = "Number of ticks remaining before the warning starts (1-30)"
    )
    default int warningThreshold()
    {
        return 10;
    }
}

package com.thralloverhead;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ThrallOverheadOverlay extends Overlay
{
    private static final Color BACKGROUND_COLOR = Color.BLACK;
    private static final Color BORDER_COLOR = Color.WHITE;

    private static final Color GHOST_COLOR = new Color(32, 181, 191);
    private static final Color SKELETON_COLOR = new Color(200, 220, 88);
    private static final Color ZOMBIE_COLOR = new Color(180, 40, 40);

    private static final Color WARNING_COLOR = Color.RED;

    private static final long FLASH_INTERVAL_MS = 200;

    private static final List<Integer> GHOST_IDS = List.of(10878, 10879, 10880);
    private static final List<Integer> SKELETON_IDS = List.of(10881, 10882, 10883);
    private static final List<Integer> ZOMBIE_IDS = List.of(10884, 10885, 10886);

    private final ThrallOverheadConfig config;

    @Getter
    @Setter
    private NPC thrall;

    @Setter
    private ThrallTimer thrallTimer;

    @Inject
    public ThrallOverheadOverlay(ThrallOverheadConfig config)
    {
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showTimer() || thrall == null || thrallTimer == null || thrallTimer.isExpired())
        {
            return null;
        }

        int barWidth = config.barWidth();
        int barHeight = config.barHeight();
        int barOffset = config.barOffset();

        Point canvasPoint = thrall.getCanvasTextLocation(
            graphics,
            "",
            thrall.getLogicalHeight() + barOffset
        );

        if (canvasPoint == null)
        {
            return null;
        }

        int x = canvasPoint.getX() - barWidth / 2;
        int y = canvasPoint.getY();

        // Flash the background red during the final few ticks
        boolean warning = config.flashWarning()
            && thrallTimer.getTicksRemaining() <= config.warningThreshold();

        boolean flashRed = warning &&
            (System.currentTimeMillis() / FLASH_INTERVAL_MS) % 2 == 0;

        // Background
        graphics.setColor(flashRed ? WARNING_COLOR : BACKGROUND_COLOR);
        graphics.fillRect(x, y, barWidth, barHeight);

        // Remaining duration
        int progressWidth = (int) (barWidth * thrallTimer.getProgress());

        graphics.setColor(getThrallColor());
        graphics.fillRect(x, y, progressWidth, barHeight);

        // Border
        if (config.showBorder())
        {
            graphics.setColor(BORDER_COLOR);
            graphics.drawRect(x, y, barWidth, barHeight);
        }
        return null;
    }

    private Color getThrallColor()
    {
        int summonedThrall = thrall.getId();

        if (GHOST_IDS.contains(summonedThrall))
        {
            return GHOST_COLOR;
        }

        if (SKELETON_IDS.contains(summonedThrall))
        {
            return SKELETON_COLOR;
        }

        if (ZOMBIE_IDS.contains(summonedThrall))
        {
            return ZOMBIE_COLOR;
        }

        return Color.GREEN;
    }
}

package com.thralloverhead;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Thrall Overhead"
)
public class ThrallOverheadPlugin extends Plugin
{
    protected static final String RESURRECT_THRALL_MESSAGE_START = "You resurrect a ";
    protected static final String RESURRECT_THRALL_MESSAGE_END = " thrall.</col>";
    protected static final int LESSER_GHOST_ID = 10878;
    protected static final int SUPERIOR_GHOST_ID = 10879;
    protected static final int GREATER_GHOST_ID = 10880;
    protected static final int LESSER_SKELETON_ID= 10881;
    protected static final int SUPERIOR_SKELETON_ID= 10882;
    protected static final int GREATER_SKELETON_ID= 10883;
    protected static final int LESSER_ZOMBIE_ID = 10884;
    protected static final int SUPERIOR_ZOMBIE_ID = 10885;
    protected static final int GREATER_ZOMBIE_ID = 10886;

    @Inject
    private Client client;

    @Inject
    private ThrallOverheadConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ThrallOverheadOverlay overlay;

    private ThrallTimer thrallTimer;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        log.debug("Thrall Timer started!");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);

        thrallTimer = null;
        overlay.setThrallTimer(null);
        overlay.setThrall(null);

        log.debug("Thrall Timer stopped!");
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage();

        if (message.contains(RESURRECT_THRALL_MESSAGE_START)
            && message.endsWith(RESURRECT_THRALL_MESSAGE_END))
        {
            int duration = client.getBoostedSkillLevel(Skill.MAGIC);

            // Combat Achievement master tier doubles thrall duration.
            if (client.getVarbitValue(VarbitID.CA_TIER_STATUS_MASTER) == 2)
            {
                duration *= 2;
            }

            thrallTimer = new ThrallTimer(duration);
            overlay.setThrallTimer(thrallTimer);

            log.debug("Thrall summoned. Duration: {} ticks", duration);
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (thrallTimer == null)
        {
            return;
        }

        thrallTimer.tick();

        if (thrallTimer.isExpired())
        {
            thrallTimer = null;
            overlay.setThrallTimer(null);
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        NPC npc = event.getNpc();

        log.info("NPC spawned: {} | ID: {}", npc.getName(), npc.getId());

        if (isThrall(npc))
        {
            overlay.setThrall(npc);
            log.info("Thrall detected! ID: {}", npc.getId());
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        if (event.getNpc() == overlay.getThrall())
        {
            overlay.setThrall(null);
            log.debug("Thrall despawned.");
        }
    }

    private boolean isThrall(NPC npc)
    {
        switch (npc.getId())
        {
            case LESSER_GHOST_ID:
            case SUPERIOR_GHOST_ID:
            case GREATER_GHOST_ID:
            case LESSER_SKELETON_ID:
            case SUPERIOR_SKELETON_ID:
            case GREATER_SKELETON_ID:
            case LESSER_ZOMBIE_ID:
            case SUPERIOR_ZOMBIE_ID:
            case GREATER_ZOMBIE_ID:
                return true;

            default:
                return false;
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            log.debug("Thrall Timer logged in.");
        }
    }

    @Provides
    ThrallOverheadConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ThrallOverheadConfig.class);
    }
}

package com.thralloverhead;

public class ThrallTimer
{
    private final int duration;
    private int ticksRemaining;

    public ThrallTimer(int duration)
    {
        if (duration <= 0)
        {
            throw new IllegalArgumentException("Duration must be greater than zero");
        }

        this.duration = duration;
        this.ticksRemaining = duration;
    }

    public void tick()
    {
        if (!isExpired())
        {
            ticksRemaining--;
        }
    }

    public int getTicksRemaining()
    {
        return ticksRemaining;
    }

    public int getDuration()
    {
        return duration;
    }

    public boolean isExpired()
    {
        return ticksRemaining <= 0;
    }

    public double getProgress()
    {
        return (double) ticksRemaining / duration;
    }
}

